insert into SALE_CUST_SVRREPORT(SENDDATE, FINPROD_ID, ISSUEMEMBER, INORABOARD, CUS_CODE, AREA_CODE, CCY, PRINAMT, PRINAMT_RMB, PRINAMT_CONFIRM, SG_AMT, SG_AMT_RMB, SG_CONFIRM_AMT, SH_AMT, SH_AMT_RMB, SH_PRINCIPAL, SH_PRINCIPAL_RMB, SH_QTY, EXPIRE_AMT, EXPIRE_AMT_RMB, EXPIRE_AMT_PRINCIPAL, EXPIRE_AMT_PRINCIPAL_RMB, EXPIRE_AMT_QTY, REBONUS_AMT, REBONUS_AMT_RMB, REBONUS_AMT_QTY, BONUS_AMT, BONUS_AMT_RMB, QTY_ADD_AMT, QTY_ADD_AMT_RMB, QTY_ADD, QTY_MINUS_PRINCIPAL, QTY_MINUS_PRINCIPAL_RMB, QTY_MINUS, SAVE_AMT, SAVE_CUS_NUM, SAVE_AMT_RMB, SAVE_QTY, EXCHANGE_RATE, CUS_TYPE,UPDATETIME) select SENDDATE, FINPROD_ID, ISSUEMEMBER, INORABOARD, CUS_CODE, AREA_CODE, CCY, PRINAMT, PRINAMT_RMB, PRINAMT_CONFIRM, SG_AMT, SG_AMT_RMB, SG_CONFIRM_AMT, SH_AMT, SH_AMT_RMB, SH_PRINCIPAL, SH_PRINCIPAL_RMB, SH_QTY, EXPIRE_AMT, EXPIRE_AMT_RMB, EXPIRE_AMT_PRINCIPAL, EXPIRE_AMT_PRINCIPAL_RMB, EXPIRE_AMT_QTY, REBONUS_AMT, REBONUS_AMT_RMB, REBONUS_AMT_QTY, BONUS_AMT, BONUS_AMT_RMB, QTY_ADD_AMT, QTY_ADD_AMT_RMB, QTY_ADD, QTY_MINUS_PRINCIPAL, QTY_MINUS_PRINCIPAL_RMB, QTY_MINUS, SAVE_AMT, SAVE_CUS_NUM, SAVE_AMT_RMB, SAVE_QTY, EXCHANGE_RATE, CUS_TYPE,UPDATETIME from ( select TEMP.* from (
select #{item.senddate, jdbcType=DATE} SENDDATE, #{item.finprodId ,jdbcType=VARCHAR } FINPROD_ID, #{item.issuemember ,jdbcType=VARCHAR } ISSUEMEMBER, #{item.inoraboard ,jdbcType=VARCHAR } INORABOARD, #{item.cusCode ,jdbcType=VARCHAR } CUS_CODE, #{item.areaCode ,jdbcType=VARCHAR } AREA_CODE, #{item.ccy ,jdbcType=VARCHAR } CCY, CAST(#{item.prinamt ,jdbcType=DECIMAL } AS DECIMAL (30,2) )PRINAMT, CAST(#{item.prinamtRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) PRINAMT_RMB, CAST(#{item.prinamtConfirm ,jdbcType=DECIMAL } AS DECIMAL (30,4) ) PRINAMT_CONFIRM, CAST(#{item.sgAmt ,jdbcType=DECIMAL } AS DECIMAL (30,2) )SG_AMT, CAST(#{item.sgAmtRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) )SG_AMT_RMB, CAST(#{item.sgConfirmAmt ,jdbcType=DECIMAL } AS DECIMAL (30,4) ) SG_CONFIRM_AMT, CAST(#{item.shAmt ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) SH_AMT, CAST(#{item.shAmtRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) SH_AMT_RMB, CAST(#{item.shPrincipal ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) SH_PRINCIPAL, CAST(#{item.shPrincipalRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) SH_PRINCIPAL_RMB, CAST(#{item.shQty ,jdbcType=DECIMAL } AS DECIMAL (30,4) ) SH_QTY, CAST(#{item.expireAmt ,jdbcType=DECIMAL } AS DECIMAL (30,2) )EXPIRE_AMT, CAST(#{item.expireAmtRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) EXPIRE_AMT_RMB, CAST(#{item.expireAmtPrincipal ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) EXPIRE_AMT_PRINCIPAL, CAST(#{item.expireAmtPrincipalRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) EXPIRE_AMT_PRINCIPAL_RMB, CAST(#{item.expireAmtQty ,jdbcType=DECIMAL } AS DECIMAL (30,4) ) EXPIRE_AMT_QTY, CAST(#{item.rebonusAmt ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) REBONUS_AMT, CAST(#{item.rebonusAmtRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) REBONUS_AMT_RMB, CAST(#{item.rebonusAmtQty ,jdbcType=DECIMAL } AS DECIMAL (30,4) ) REBONUS_AMT_QTY, CAST(#{item.bonusAmt ,jdbcType=DECIMAL } AS DECIMAL (30,2) )BONUS_AMT, CAST(#{item.bonusAmtRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) BONUS_AMT_RMB, CAST(#{item.qtyAddAmt ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) QTY_ADD_AMT, CAST(#{item.qtyAddAmtRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) )QTY_ADD_AMT_RMB, CAST(#{item.qtyAdd ,jdbcType=DECIMAL } AS DECIMAL (30,4) ) QTY_ADD, CAST(#{item.qtyMinusPrincipal ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) QTY_MINUS_PRINCIPAL, CAST(#{item.qtyMinusPrincipalRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) QTY_MINUS_PRINCIPAL_RMB, CAST(#{item.qtyMinus ,jdbcType=DECIMAL } AS DECIMAL (30,4) ) QTY_MINUS, CAST(#{item.saveAmt ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) SAVE_AMT, CAST(#{item.saveCusNum ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) SAVE_CUS_NUM, CAST(#{item.saveAmtRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) SAVE_AMT_RMB, CAST(#{item.saveQty ,jdbcType=DECIMAL } AS DECIMAL (30,4) ) SAVE_QTY, CAST(#{item.exchangeRate ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) EXCHANGE_RATE, #{item.cusType ,jdbcType=VARCHAR } CUS_TYPE, NOW() UPDATETIME from dual
) TEMP where not exists (select 1 from SALE_CUST_SVRREPORT CII where CII.FINPROD_ID = TEMP.FINPROD_ID and CII.SENDDATE = TEMP.SENDDATE and CII.ISSUEMEMBER = TEMP.ISSUEMEMBER and CII.INORABOARD = TEMP.INORABOARD and CII.CUS_CODE = TEMP.CUS_CODE and CII.AREA_CODE = TEMP.AREA_CODE and CII.CCY = TEMP.CCY) ) de ;
UPDATE SALE_CUST_SVRREPORT as A, ( select TEMP.* from (
select #{item.senddate, jdbcType=DATE} SENDDATE, #{item.finprodId ,jdbcType=VARCHAR } FINPROD_ID, #{item.issuemember ,jdbcType=VARCHAR } ISSUEMEMBER, #{item.inoraboard ,jdbcType=VARCHAR } INORABOARD, #{item.cusCode ,jdbcType=VARCHAR } CUS_CODE, #{item.areaCode ,jdbcType=VARCHAR } AREA_CODE, #{item.ccy ,jdbcType=VARCHAR } CCY, CAST(#{item.prinamt ,jdbcType=DECIMAL } AS DECIMAL (30,2) )PRINAMT, CAST(#{item.prinamtRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) PRINAMT_RMB, CAST(#{item.prinamtConfirm ,jdbcType=DECIMAL } AS DECIMAL (30,4) ) PRINAMT_CONFIRM, CAST(#{item.sgAmt ,jdbcType=DECIMAL } AS DECIMAL (30,2) )SG_AMT, CAST(#{item.sgAmtRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) )SG_AMT_RMB, CAST(#{item.sgConfirmAmt ,jdbcType=DECIMAL } AS DECIMAL (30,4) ) SG_CONFIRM_AMT, CAST(#{item.shAmt ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) SH_AMT, CAST(#{item.shAmtRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) SH_AMT_RMB, CAST(#{item.shPrincipal ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) SH_PRINCIPAL, CAST(#{item.shPrincipalRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) SH_PRINCIPAL_RMB, CAST(#{item.shQty ,jdbcType=DECIMAL } AS DECIMAL (30,4) ) SH_QTY, CAST(#{item.expireAmt ,jdbcType=DECIMAL } AS DECIMAL (30,2) )EXPIRE_AMT, CAST(#{item.expireAmtRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) EXPIRE_AMT_RMB, CAST(#{item.expireAmtPrincipal ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) EXPIRE_AMT_PRINCIPAL, CAST(#{item.expireAmtPrincipalRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) EXPIRE_AMT_PRINCIPAL_RMB, CAST(#{item.expireAmtQty ,jdbcType=DECIMAL } AS DECIMAL (30,4) ) EXPIRE_AMT_QTY, CAST(#{item.rebonusAmt ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) REBONUS_AMT, CAST(#{item.rebonusAmtRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) REBONUS_AMT_RMB, CAST(#{item.rebonusAmtQty ,jdbcType=DECIMAL } AS DECIMAL (30,4) ) REBONUS_AMT_QTY, CAST(#{item.bonusAmt ,jdbcType=DECIMAL } AS DECIMAL (30,2) )BONUS_AMT, CAST(#{item.bonusAmtRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) BONUS_AMT_RMB, CAST(#{item.qtyAddAmt ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) QTY_ADD_AMT, CAST(#{item.qtyAddAmtRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) )QTY_ADD_AMT_RMB, CAST(#{item.qtyAdd ,jdbcType=DECIMAL } AS DECIMAL (30,4) ) QTY_ADD, CAST(#{item.qtyMinusPrincipal ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) QTY_MINUS_PRINCIPAL, CAST(#{item.qtyMinusPrincipalRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) QTY_MINUS_PRINCIPAL_RMB, CAST(#{item.qtyMinus ,jdbcType=DECIMAL } AS DECIMAL (30,4) ) QTY_MINUS, CAST(#{item.saveAmt ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) SAVE_AMT, CAST(#{item.saveCusNum ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) SAVE_CUS_NUM, CAST(#{item.saveAmtRmb ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) SAVE_AMT_RMB, CAST(#{item.saveQty ,jdbcType=DECIMAL } AS DECIMAL (30,4) ) SAVE_QTY, CAST(#{item.exchangeRate ,jdbcType=DECIMAL } AS DECIMAL (30,2) ) EXCHANGE_RATE, #{item.cusType ,jdbcType=VARCHAR } CUS_TYPE, NOW() UPDATETIME from dual
) TEMP ) AS B set A.SENDDATE = B.SENDDATE, A.ISSUEMEMBER = B.ISSUEMEMBER, A.INORABOARD = B.INORABOARD, A.CUS_CODE = B.CUS_CODE, A.AREA_CODE = B.AREA_CODE, A.CCY = B.CCY, A.PRINAMT = B.PRINAMT, A.PRINAMT_RMB = B.PRINAMT_RMB, A.PRINAMT_CONFIRM = B.PRINAMT_CONFIRM, A.SG_AMT = B.SG_AMT, A.SG_AMT_RMB = B.SG_AMT_RMB, A.SG_CONFIRM_AMT = B.SG_CONFIRM_AMT, A.SH_AMT = B.SH_AMT, A.SH_AMT_RMB = B.SH_AMT_RMB, A.SH_PRINCIPAL = B.SH_PRINCIPAL, A.SH_PRINCIPAL_RMB = B.SH_PRINCIPAL_RMB, A.SH_QTY = B.SH_QTY, A.EXPIRE_AMT = B.EXPIRE_AMT, A.EXPIRE_AMT_RMB = B.EXPIRE_AMT_RMB, A.EXPIRE_AMT_PRINCIPAL = B.EXPIRE_AMT_PRINCIPAL, A.EXPIRE_AMT_PRINCIPAL_RMB = B.EXPIRE_AMT_PRINCIPAL_RMB, A.EXPIRE_AMT_QTY = B.EXPIRE_AMT_QTY, A.REBONUS_AMT = B.REBONUS_AMT, A.REBONUS_AMT_RMB = B.REBONUS_AMT_RMB, A.REBONUS_AMT_QTY = B.REBONUS_AMT_QTY, A.BONUS_AMT = B.BONUS_AMT, A.BONUS_AMT_RMB = B.BONUS_AMT_RMB, A.QTY_ADD_AMT = B.QTY_ADD_AMT, A.QTY_ADD_AMT_RMB = B.QTY_ADD_AMT_RMB, A.QTY_ADD = B.QTY_ADD, A.QTY_MINUS_PRINCIPAL = B.QTY_MINUS_PRINCIPAL, A.QTY_MINUS_PRINCIPAL_RMB = B.QTY_MINUS_PRINCIPAL_RMB, A.QTY_MINUS = B.QTY_MINUS , A.SAVE_AMT = B.SAVE_AMT, A.SAVE_CUS_NUM = B.SAVE_CUS_NUM, A.SAVE_AMT_RMB = B.SAVE_AMT_RMB, A.SAVE_QTY = B.SAVE_QTY, A.EXCHANGE_RATE = B.EXCHANGE_RATE, A.CUS_TYPE = B.CUS_TYPE, A.UPDATETIME = B.UPDATETIME where A.FINPROD_ID = B.FINPROD_ID and A.SENDDATE = B.SENDDATE and A.ISSUEMEMBER = B.ISSUEMEMBER and A.INORABOARD = B.INORABOARD and A.CUS_CODE = B.CUS_CODE and A.AREA_CODE = B.AREA_CODE and A.CCY = B.CCY;
